import { useEffect, useState } from 'react';
import axios from 'axios';

function Dashboard() {
  const [items, setItems] = useState([]);
  const userId = localStorage.getItem('userId'); // Store this after login

  useEffect(() => {
    const fetchItems = async () => {
      try {
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/items/user`, {
          params: { userId }
        });
        setItems(res.data);
      } catch (err) {
        console.error('Dashboard error:', err.response?.data || err.message);
      }
    };
    fetchItems();
  }, [userId]);

  return (
    <div style={{ maxWidth: '600px', margin: 'auto' }}>
      <h2>Your Reported Items</h2>
      <ul>
        {items.map(item => (
          <li key={item._id}>
            <strong>{item.title}</strong> ({item.type})<br />
            {item.description}<br />
            <em>{item.location} — {new Date(item.date).toLocaleDateString()}</em>
            <button onClick={() => markResolved(item._id)}>Mark as Resolved</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
const markResolved = async (itemId) => {
  try {
    await axiosAuth.post('/items/resolve', { itemId });
    alert('Item marked as resolved');
    fetchItems(); // refresh
  } catch (err) {
    console.error(err);
  }
};

export default Dashboard;
